<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/client';const items=ref<any[]>([]),show=ref(false),form=ref({request_type:'lease_activation',resource_type:'lease',resource_id:'',title:'',summary:'',reviewers:[] as string[]}),reviewerText=ref('');async function load(){items.value=(await api.get('/approvals',{params:{page:1,page_size:100}})).data.items||[]}async function create(){form.value.reviewers=reviewerText.value.split(',').map(x=>x.trim()).filter(Boolean);await api.post('/approvals',form.value);show.value=false;await load()}async function decide(id:string,decision:string){await api.post(`/approvals/${id}/decision`,{decision,comment:decision==='approved'?'后台审批通过':'后台审批驳回'});await load()}onMounted(load)</script>
<template><div class="page"><div class="page-title"><div><h1>审批中心</h1><p>统一处理租约生效、账单减免、押金扣退与退租结算复核</p></div><button class="primary-button" @click="show=true">＋ 发起审批</button></div><section class="card"><table v-if="items.length" class="data-table"><thead><tr><th>审批标题</th><th>类型</th><th>业务对象</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="x in items" :key="x.ID"><td><strong>{{x.Title}}</strong><div>{{x.Summary}}</div></td><td>{{x.RequestType}}</td><td>{{x.ResourceType}} · {{x.ResourceID}}</td><td><span class="status-badge" :class="x.Status">{{x.Status}}</span></td><td>{{x.CreatedAt}}</td><td><div v-if="x.Status==='pending'" class="action-group"><button class="primary-button" @click="decide(x.ID,'approved')">通过</button><button class="secondary-button" @click="decide(x.ID,'rejected')">驳回</button></div></td></tr></tbody></table><div v-else class="empty-state"><b>暂无审批事项</b><span>可从业务流程发起第一条审批</span></div></section><div v-if="show" class="modal-mask" @click.self="show=false"><div class="modal"><div class="modal-header"><h3>发起审批</h3><button class="close-button" @click="show=false">×</button></div><div class="modal-body"><div class="form-grid"><label><span>审批类型</span><select v-model="form.request_type"><option value="lease_activation">租约生效</option><option value="bill_discount">账单减免</option><option value="deposit_adjustment">押金扣退</option><option value="settlement_completion">退租结算</option></select></label><label><span>资源类型</span><input v-model="form.resource_type"></label><label><span>资源 ID</span><input v-model="form.resource_id"></label><label><span>审批标题</span><input v-model="form.title"></label><label class="full"><span>审批说明</span><textarea v-model="form.summary" rows="3"></textarea></label><label class="full"><span>复核人用户 ID（逗号分隔）</span><input v-model="reviewerText"></label></div></div><div class="modal-footer"><button class="secondary-button" @click="show=false">取消</button><button class="primary-button" @click="create">提交</button></div></div></div></div></template>
